/**
 * Regenerates src/data/skillCoefficients.ts from the plugin's skill coefficient skeleton.
 *
 * Usage: npm run sync:coefficients [-- <path to skill-coefficients-skeleton.yml>]
 * Default input assumes the plugin repository is checked out next to this one.
 * Not part of `npm run build`: CI has no plugin checkout, so the generated file is committed.
 */
import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const input = path.resolve(
  process.argv[2] ??
    path.join(root, '..', 'rpgskills.github.io', 'rpgskills-common', 'src', 'main', 'resources', 'Config', 'skill-coefficients-skeleton.yml'),
);
const output = path.join(root, 'src', 'data', 'skillCoefficients.ts');

const HEADER = /^# =+ (\w+) \(/;
// "#   Rising.0_45_0_036  [scaled]  base=0.45 levelScale=0.036  # 피해"
const ENTRY = /^#   ([\w.]+)\s+\[(scaled|linear|value)\]\s+base=(\S+)(?:\s+(?:levelScale|levelBonus)=(\S+))?(?:\s+#\s*(.*))?$/;

const lines = (await readFile(input, 'utf-8')).split(/\r?\n/);
const classes = {};
const skipped = [];
let current = null;

for (const line of lines) {
  const header = HEADER.exec(line);
  if (header) {
    // Plugin ids are PascalCase ("FireMage"), site ids are camelCase ("fireMage").
    current = header[1][0].toLowerCase() + header[1].slice(1);
    classes[current] = [];
    continue;
  }
  const entry = ENTRY.exec(line);
  if (!entry || !current) continue;
  const [, key, kind, base, step, note] = entry;
  // Some defaults are derived from other coefficients in Java (e.g. "vineWhipDisplayDamage(1)").
  if (!Number.isFinite(Number(base))) {
    skipped.push(`${current}.${key} (base=${base})`);
    continue;
  }
  classes[current].push({ key, kind, base: Number(base), step: Number(step ?? 0), note: (note ?? '').trim() });
}

const ids = Object.keys(classes);
assert.equal(ids.length, 32, `expected 32 classes in ${input}, found ${ids.length}`);
for (const id of ids) {
  assert.ok(classes[id].length > 0, `${id} has no coefficients`);
  assert.ok(existsSync(path.join(root, 'src', 'data', 'classDetails', `${id}.ts`)), `${id} has no class detail file`);
  for (const c of classes[id]) {
    assert.ok(Number.isFinite(c.base) && Number.isFinite(c.step), `${id}.${c.key} has a non-numeric value`);
  }
}

const body = `/**
 * Generated by scripts/sync-skill-coefficients.mjs from the plugin's skill-coefficients-skeleton.yml.
 * Do not edit by hand; run \`npm run sync:coefficients\` after changing coefficients in the plugin.
 *
 * scaled: base * (1 + level * step), linear: base + level * step, value: base (level independent).
 */
export type CoefficientKind = 'scaled' | 'linear' | 'value';

export type SkillCoefficient = {
  /** Config key under SkillCoefficients.<Class>, e.g. "Rising.0_45_0_036" */
  key: string;
  kind: CoefficientKind;
  base: number;
  /** levelScale for scaled, levelBonus for linear, 0 for value */
  step: number;
  /** Korean note from the plugin skeleton, e.g. "피해" */
  note: string;
};

export const SKILL_COEFFICIENTS: Record<string, SkillCoefficient[]> = ${JSON.stringify(classes, null, 2)};
`;

await writeFile(output, body, 'utf-8');
const total = ids.reduce((sum, id) => sum + classes[id].length, 0);
console.log(`Wrote ${path.relative(root, output)}: ${ids.length} classes, ${total} coefficients.`);
if (skipped.length) console.warn(`Skipped non-numeric defaults: ${skipped.join(', ')}`);
